1	export type Cell = [number, number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const areNeighbors = (cell: Cell, other: Cell): boolean => {
7	  const [x, y] = cell;
8	  const [otherX, otherY] = other;
9	  return (
10	    Math.abs(otherX - x) <= 1 &&
11	    Math.abs(otherY - y) <= 1 &&
12	    !isSameCell(cell, other)
13	  );
14	};
15	
16	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
17	  liveCells.filter((liveCell) => areNeighbors(cell, liveCell)).length;
18	
19	const survives = (neighborCount: number): boolean =>
20	  neighborCount === 2 || neighborCount === 3;
21	
22	const isBorn = (neighborCount: number): boolean => neighborCount === 3;
23	
24	const isAlive = (cell: Cell, liveCells: Cell[]): boolean =>
25	  liveCells.some((liveCell) => isSameCell(cell, liveCell));
26	
27	const NEIGHBOR_OFFSETS: Cell[] = [
28	  [-1, -1],
29	  [-1, 0],
30	  [-1, 1],
31	  [0, -1],
32	  [0, 1],
33	  [1, -1],
34	  [1, 0],
35	  [1, 1],
36	];
37	
38	const neighborsOf = ([x, y]: Cell): Cell[] =>
39	  NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
40	
41	const withoutDuplicateCells = (cells: Cell[]): Cell[] =>
42	  cells.filter(
43	    (cell, index) =>
44	      index === cells.findIndex((other) => isSameCell(cell, other)),
45	  );
46	
47	const birthCandidates = (liveCells: Cell[]): Cell[] =>
48	  withoutDuplicateCells(
49	    liveCells.flatMap(neighborsOf).filter((cell) => !isAlive(cell, liveCells)),
50	  );
51	
52	export function nextGeneration(liveCells: Cell[]): Cell[] {
53	  const survivors = liveCells.filter((cell) =>
54	    survives(countLiveNeighbors(cell, liveCells)),
55	  );
56	  const born = birthCandidates(liveCells).filter((cell) =>
57	    isBorn(countLiveNeighbors(cell, liveCells)),
58	  );
59	  return [...survivors, ...born];
60	}
