const cellsWhoseNeighborCount = (
  candidates: Cell[],
  liveCells: Cell[],
  satisfiesRule: (neighborCount: number) => boolean,
): Cell[] =>
  candidates.filter((cell) =>
    satisfiesRule(countLiveNeighbors(cell, liveCells)),
  );

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = cellsWhoseNeighborCount(liveCells, liveCells, survives);
  const born = cellsWhoseNeighborCount(
    birthCandidates(liveCells),
    liveCells,
    isBorn,
  );
  return [...survivors, ...born];
}
